"""The HTML report.

The HTML report is the default deliverable, so it is tested like one:

* it is generated by ``cc-eval run`` without any extra flag;
* the numbers it shows are the numbers of ``report.json`` (the report is
  rendered from the same model - it never recomputes anything);
* it is self-contained: no external resource is referenced;
* the interactions work: tabs, case filtering, expanding a case, switching
  the trace view;
* a partial or failed experiment is marked as such and never shown as a
  success;
* agent output cannot inject HTML or JavaScript;
* secrets never reach the report.
"""

from __future__ import annotations

import json
import re
from pathlib import Path

from typer.testing import CliRunner

from cc_eval.cli.main import app
from cc_eval.reports import build_report_model, render_html
from cc_eval.reports.html_report import json_for_script, load_model_json

from .conftest import run_experiment, write_benchmark, write_experiment, write_framework

runner = CliRunner()


def _invoke(*args: str):
    return runner.invoke(app, list(args))


def _setup(tmp_path: Path, *, repetitions: int = 2) -> tuple[Path, Path]:
    """A baseline that finds nothing and a candidate that finds the defect."""
    baseline = write_framework(tmp_path / "fw" / "baseline", detectors=[("alpha", r"nothing-matches")])
    candidate = write_framework(tmp_path / "fw" / "candidate", detectors=[("alpha", r"alpha")])
    benchmark = write_benchmark(
        tmp_path / "bench",
        known_defects=[
            {
                "id": "D001",
                "category": "alpha",
                "severity": "high",
                "description": "the input mentions alpha",
                "match_keywords": ["alpha"],
            }
        ],
    )
    spec_file = write_experiment(
        tmp_path / "exp.yaml",
        baseline_dir=baseline,
        candidate_dir=candidate,
        benchmark_dir=benchmark,
        repetitions=repetitions,
        expected_changes=["skills/test_skill.py"],
    )
    return spec_file, benchmark


def _embedded_payload(html: str) -> dict:
    """The report payload embedded in the HTML page."""
    match = re.search(
        r'<script id="cc-eval-report-data" type="application/json">(.*?)</script>',
        html,
        re.S,
    )
    assert match, "the report must embed its data for the interactive parts"
    return json.loads(match.group(1))


# --------------------------------------------------------------------------- #
# generation
# --------------------------------------------------------------------------- #


def test_run_generates_an_html_report(tmp_path: Path) -> None:
    root = tmp_path / "ws"
    spec_file, _ = _setup(tmp_path)

    result = _invoke("run", "EXP-CLI", "--runner", "fake", "--root", str(root), "--file", str(spec_file))
    assert result.exit_code == 0, result.output

    html_path = root / "reports" / "EXP-T001" / "report.html"
    assert html_path.exists(), "cc-eval run must produce report.html"
    assert "html report:" in result.output

    html = html_path.read_text(encoding="utf-8")
    assert html.lstrip().startswith("<!doctype html>")
    assert "EXP-T001" in html
    # The bundle keeps the JSON and the Markdown next to the HTML.
    assert (root / "reports" / "EXP-T001" / "report.json").exists()
    assert (root / "reports" / "EXP-T001" / "report.md").exists()
    # The legacy flat files stay in place.
    assert (root / "reports" / "EXP-T001.json").exists()
    assert (root / "reports" / "EXP-T001.md").exists()


def test_report_and_render_can_rebuild_the_html_without_running(tmp_path: Path) -> None:
    root = tmp_path / "ws"
    spec_file, _ = _setup(tmp_path)
    _invoke("run", "EXP-CLI", "--runner", "fake", "--root", str(root), "--file", str(spec_file))

    html_path = root / "reports" / "EXP-T001" / "report.html"
    html_path.unlink()

    result = _invoke("render", "EXP-T001", "--root", str(root), "--file", str(spec_file))
    assert result.exit_code == 0, result.output
    assert html_path.exists(), "render must rebuild the HTML from the stored runs"
    assert "no experiment was executed" in result.output

    # Rendering must not create new runs.
    run_files = list((root / "runs" / "EXP-T001").glob("*.json"))
    assert len(run_files) == 4  # 2 variants x 1 case x 2 repetitions


def test_report_command_supports_the_html_format(tmp_path: Path) -> None:
    root = tmp_path / "ws"
    spec_file, _ = _setup(tmp_path)
    _invoke("run", "EXP-CLI", "--runner", "fake", "--root", str(root), "--file", str(spec_file))

    target = tmp_path / "custom.html"
    result = _invoke(
        "report",
        "EXP-T001",
        "--root",
        str(root),
        "--file",
        str(spec_file),
        "--format",
        "html",
        "--output",
        str(target),
    )
    assert result.exit_code == 0, result.output
    assert target.exists()
    assert target.read_text(encoding="utf-8").lstrip().startswith("<!doctype html>")


# --------------------------------------------------------------------------- #
# consistency with report.json
# --------------------------------------------------------------------------- #


def test_html_numbers_match_report_json(tmp_path: Path) -> None:
    root = tmp_path / "ws"
    spec_file, _ = _setup(tmp_path)
    _invoke("run", "EXP-CLI", "--runner", "fake", "--root", str(root), "--file", str(spec_file))

    html = (root / "reports" / "EXP-T001" / "report.html").read_text(encoding="utf-8")
    payload = json.loads((root / "reports" / "EXP-T001" / "report.json").read_text(encoding="utf-8"))
    embedded = _embedded_payload(html)

    # The page carries exactly the JSON report - the two cannot drift.
    assert embedded["report"] == payload["report"]
    assert embedded["cases"] == payload["cases"]
    assert embedded["metadata"] == payload["metadata"]

    # And the numbers are on the page, not only in the payload.
    recall = next(m for m in payload["report"]["metrics"] if m["metric"] == "recall")
    assert recall["baseline"] == 0.0
    assert recall["candidate"] == 1.0
    assert "recall" in html.lower()
    assert "CASE-001" in html


def test_report_json_can_be_replayed_into_a_report(tmp_path: Path) -> None:
    """The JSON report is replayable: the HTML can be rebuilt from it alone."""
    root = tmp_path / "ws"
    spec_file, _ = _setup(tmp_path)
    _invoke("run", "EXP-CLI", "--runner", "fake", "--root", str(root), "--file", str(spec_file))

    json_path = root / "reports" / "EXP-T001" / "report.json"
    model = load_model_json(json_path)
    html = render_html(model)
    assert "<!doctype html>" in html
    assert _embedded_payload(html)["report"] == json.loads(json_path.read_text(encoding="utf-8"))["report"]


