def test_report_has_the_four_tabs(tmp_path: Path) -> None:
    root = tmp_path / "ws"
    spec_file, _ = _setup(tmp_path)
    _invoke("run", "EXP-CLI", "--runner", "fake", "--root", str(root), "--file", str(spec_file))
    html = (root / "reports" / "EXP-T001" / "report.html").read_text(encoding="utf-8")

    for tab in ("tab-overview", "tab-cases", "tab-traces", "tab-metadata"):
        assert f'id="{tab}"' in html, f"the report must have a {tab} tab"
        assert f'data-tab="{tab}"' in html

    # The interactive parts are wired up.
    assert "activateTab" in html
    assert "applyFilters" in html
    assert "toggleDetail" in html
    assert "showTraceRun" in html


