# --------------------------------------------------------------------------- #
# honesty about partial and failed experiments
# --------------------------------------------------------------------------- #


def test_failed_runs_are_marked_as_incomplete(tmp_path: Path, workspace_root) -> None:
    """A broken skill must not be presented as a successful experiment."""
    baseline = write_framework(tmp_path / "fw" / "baseline", detectors=[("alpha", r"alpha")])
    candidate = write_framework(tmp_path / "fw" / "candidate", detectors=[("alpha", r"alpha")])
    # Break the candidate skill at run time: the run is recorded as an error.
    (candidate / "skills" / "test_skill.py").write_text(
        'def run(payload):\n    raise RuntimeError("boom")\n', encoding="utf-8"
    )
    benchmark = write_benchmark(
        tmp_path / "bench",
        known_defects=[
            {"id": "D001", "category": "alpha", "description": "alpha", "match_keywords": ["alpha"]}
        ],
    )
    spec_file = write_experiment(
        tmp_path / "exp.yaml",
        baseline_dir=baseline,
        candidate_dir=candidate,
        benchmark_dir=benchmark,
        repetitions=1,
        expected_changes=["skills/test_skill.py"],
    )
    records, _ = run_experiment(spec_file, workspace_root)

    from cc_eval.comparison.compare import compare
    from cc_eval.core.experiment import load_experiment

    spec = load_experiment(spec_file)
    comparison = compare(spec, records, dataset_version="v1", dataset_hash="abc", evaluator="det")
    model = build_report_model(spec, comparison, records)

    assert model.status == "incomplete"
    assert model.metadata.status == "incomplete"
    assert any("PARTIAL" in caveat for caveat in model.metadata.caveats)

    html = render_html(model)
    assert "incomplete" in html
    assert "This report is partial" in html
    # The banner says the verdict must not be read as a success.
    assert "must not be read as a successful experiment" in html
    # The failure itself is visible.
    assert "boom" in html


def test_a_run_that_cannot_start_is_reported_as_incomplete(tmp_path: Path) -> None:
    """A skill that cannot even be loaded kills the run before it is recorded."""
    root = tmp_path / "ws"
    baseline = write_framework(tmp_path / "fw" / "baseline", detectors=[("alpha", r"alpha")])
    candidate = write_framework(tmp_path / "fw" / "candidate", detectors=[("alpha", r"alpha")])
    (candidate / "skills" / "test_skill.py").write_text(
        'raise RuntimeError("cannot load")\n', encoding="utf-8"
    )
    benchmark = write_benchmark(tmp_path / "bench")
    spec_file = write_experiment(
        tmp_path / "exp.yaml",
        baseline_dir=baseline,
        candidate_dir=candidate,
        benchmark_dir=benchmark,
        repetitions=1,
        expected_changes=["skills/test_skill.py"],
    )
    result = _invoke("run", "EXP-CLI", "--runner", "fake", "--root", str(root), "--file", str(spec_file))
    assert result.exit_code == 0, result.output
    assert "warning" in result.output.lower()

    html = (root / "reports" / "EXP-T001" / "report.html").read_text(encoding="utf-8")
    assert "incomplete" in html
    assert "This report is partial" in html


def test_experiment_without_runs_is_failed(tmp_path: Path) -> None:
    from cc_eval.comparison.compare import compare
    from cc_eval.core.experiment import load_experiment

    baseline = write_framework(tmp_path / "fw" / "baseline", detectors=[("alpha", r"alpha")])
    candidate = write_framework(tmp_path / "fw" / "candidate", detectors=[("alpha", r"alpha")])
    benchmark = write_benchmark(tmp_path / "bench")
    spec_file = write_experiment(
        tmp_path / "exp.yaml",
        baseline_dir=baseline,
        candidate_dir=candidate,
        benchmark_dir=benchmark,
    )
    spec = load_experiment(spec_file)
    comparison = compare(spec, [])
    model = build_report_model(spec, comparison, [])

    assert model.status == "failed"
    html = render_html(model)
    assert "This experiment did not complete" in html


def test_missing_values_are_shown_as_na_not_zero(tmp_path: Path) -> None:
    """The fake runner does not report a cost: the report must say n/a."""
    root = tmp_path / "ws"
    spec_file, _ = _setup(tmp_path)
    _invoke("run", "EXP-CLI", "--runner", "fake", "--root", str(root), "--file", str(spec_file))
    html = (root / "reports" / "EXP-T001" / "report.html").read_text(encoding="utf-8")

    payload = _embedded_payload(html)
    cost = next(
        (m for m in payload["report"]["metrics"] if m["metric"] == "cost_usd"), None
    )
    if cost is not None:
        assert cost["baseline"] is None
    assert "n/a" in html
    assert "never means zero" in html


# --------------------------------------------------------------------------- #
# safety
# --------------------------------------------------------------------------- #


def test_report_is_self_contained(tmp_path: Path) -> None:
    """No external resource: the report must work offline."""
    root = tmp_path / "ws"
    spec_file, _ = _setup(tmp_path)
    _invoke("run", "EXP-CLI", "--runner", "fake", "--root", str(root), "--file", str(spec_file))
    html = (root / "reports" / "EXP-T001" / "report.html").read_text(encoding="utf-8")

    assert "http://" not in html
    assert "https://" not in html.replace("http://www.w3.org", "")
    assert "<script src" not in html
    assert "<link " not in html
    assert "@import" not in html


def test_agent_output_cannot_inject_html_or_javascript(tmp_path: Path) -> None:
    """A malicious agent output must stay text."""
    payload = "<script>alert('xss')</script>"
    secretish = "sk-ant-api03-INJECTIONTESTVALUE1234567890"
    baseline = write_framework(tmp_path / "fw" / "baseline", detectors=[("alpha", r"alpha")])
    candidate = write_framework(tmp_path / "fw" / "candidate", detectors=[("alpha", r"alpha")])
    skill_path = candidate / "skills" / "test_skill.py"
    skill_path.write_text(
        skill_path.read_text(encoding="utf-8").replace(
            '"evidence": "pattern matched",',
            f'"evidence": "{payload} {secretish}",',
        ),
        encoding="utf-8",
    )
    benchmark = write_benchmark(
        tmp_path / "bench",
        known_defects=[
            {"id": "D001", "category": "alpha", "description": "alpha", "match_keywords": ["alpha"]}
        ],
    )
    spec_file = write_experiment(
        tmp_path / "exp.yaml",
        baseline_dir=baseline,
        candidate_dir=candidate,
        benchmark_dir=benchmark,
        repetitions=1,
        expected_changes=["skills/test_skill.py"],
    )
    records, _ = run_experiment(spec_file, tmp_path / "ws")

    from cc_eval.comparison.compare import compare
    from cc_eval.core.experiment import load_experiment

    spec = load_experiment(spec_file)
    comparison = compare(spec, records, dataset_version="v1", dataset_hash="abc", evaluator="det")
    model = build_report_model(spec, comparison, records)
    html = render_html(model)

    assert "<script>alert('xss')</script>" not in html
    assert "&lt;script&gt;" in html or "REDACTED" in html
    # The credential never reaches the report.
    assert secretish not in html
    assert "REDACTED" in html


def test_json_for_script_cannot_break_out_of_a_script_block() -> None:
    payload = {"evil": "</script><script>alert(1)</script>"}
    text = json_for_script(payload)
    assert "</script>" not in text
    assert "<" not in text
    assert json.loads(text)["evil"] == payload["evil"]


# --------------------------------------------------------------------------- #
# customisation
# --------------------------------------------------------------------------- #


def test_a_custom_template_can_be_used(tmp_path: Path) -> None:
    root = tmp_path / "ws"
    spec_file, _ = _setup(tmp_path)
    _invoke("run", "EXP-CLI", "--runner", "fake", "--root", str(root), "--file", str(spec_file))

    template = tmp_path / "custom.html.j2"
    template.write_text(
        "<!doctype html><html><body><h1>{{ spec.id }}</h1>"
        "<p>{{ metadata.status }}</p></body></html>",
        encoding="utf-8",
    )
    target = tmp_path / "custom.html"
    result = _invoke(
        "render",
        "EXP-T001",
        "--root",
        str(root),
        "--file",
        str(spec_file),
        "--template",
        str(template),
        "--output",
        str(target),
    )
    assert result.exit_code == 0, result.output
    rendered = target.read_text(encoding="utf-8")
    assert "<h1>EXP-T001</h1>" in rendered
    assert "<p>complete</p>" in rendered


