def test_registry_links_the_experiment_to_its_reports(tmp_path: Path) -> None:
    root = tmp_path / "ws"
    spec_file, _ = _setup(tmp_path)
    _invoke("run", "EXP-CLI", "--runner", "fake", "--root", str(root), "--file", str(spec_file))

    result = _invoke("registry", "reports", "--root", str(root))
    assert result.exit_code == 0, result.output
    assert "EXP-T001" in result.output
    assert "report.html" in result.output
